#include <memory>
#include <iostream>

class Data { public: ~Data() { std::cout << "Data Deleted\n"; } };

// Source: transfers ownership to caller
std::auto_ptr<Data> factory() {
    std::auto_ptr<Data> ptr(new Data);
    return ptr; // Ownership transfer via destructive copy
}

// Sink: receives ownership, deletes upon exit
void process_and_destroy(std::auto_ptr<Data> p) {
    if (p.get() != nullptr) {
        std::cout << "Processing Data...\n";
    }
    // p goes out of scope, Data is deleted.
}

int main() {
    std::auto_ptr<Data> caller_p = factory(); // caller_p now owns it
    process_and_destroy(caller_p);            // Ownership transferred to sink
    // caller_p is now null
}
